import fs from 'node:fs';import {createServer} from 'node:http';
import {createStudio} from 'file:///C:/Users/Cheng/Documents/deepseek-harness/default-workspace/miliastra-beyond-simulator/studio/index.js';
const OUT='outputs/nahida-two-actions-20261015';
// Keep the official shape renderer and remove only the preview environment
// background. This makes the screenshot transparent without substituting art.
let renderer=fs.readFileSync('C:/Users/Cheng/Documents/deepseek-harness/default-workspace/miliastra-beyond-simulator/studio/host-png.js','utf8');
renderer=renderer.replace("from './play/image-fill.js'","from 'file:///C:/Users/Cheng/Documents/deepseek-harness/default-workspace/miliastra-beyond-simulator/studio/play/image-fill.js'")
 .replace('const require = createRequire(import.meta.url)',"const require = createRequire('C:/Users/Cheng/Documents/deepseek-harness/default-workspace/miliastra-beyond-simulator/package.json')")
 .replace('drawStageBackground(ctx, size.width, size.height)','/* transparent preview environment */');
fs.writeFileSync(OUT+'/transparent-native-renderer.mjs',renderer);
const {renderPaintPng}=await import('../'+OUT+'/transparent-native-renderer.mjs');
const studio=createStudio(JSON.parse(fs.readFileSync(OUT+'/reimported.simulator.save.json')));
studio.playStart({canvasId:'pc-16-9'});studio.playStep(1/60,{observe:false});studio.playServerSend('AnimationControl',['pause',1]);
let paused=true,position=0,mirror=1;
function command(op,value){if(op==='pause')paused=value===1;if(op==='frame'||op==='step')paused=true;if(op==='position')position=Number(value);if(op==='mirror')mirror=Number(value);studio.playServerSend('AnimationControl',[op,value]);studio.playStep(1/60,{observe:false});}
function state(){const s=studio.playGet({view:true});const text=s.scene.nodes.find(n=>n.name==='Status')?.text||'';const match=/^(idle|move) (\d)\/4/.exec(text);return {action:match?.[1]||'idle',frame:Number(match?.[2]||1),paused,position,mirror,status:text,images:s.scene.nodes.filter(n=>/^S\d{4}$/.test(n.name)).length,errors:s.logs.filter(l=>['error','lua-error'].includes(l.level))};}
setInterval(()=>{if(!paused)studio.playStep(.03,{observe:false})},30);
const html=`<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>草神 · 两组图元动作操作</title><style>body{margin:0;background:#edf1f4;color:#29392e;font:16px system-ui}header{padding:14px 20px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}button,a{padding:8px 12px;border-radius:6px;border:1px solid #a9b5ac;background:white;color:#26583b;cursor:pointer}p{margin:10px 20px}#stage{max-width:1600px;margin:auto;background:conic-gradient(#e4e7e9 25%,#fafafa 0 50%,#e4e7e9 0 75%,#fafafa 0) 0 0/28px 28px}#screen{width:100%;display:block}#ref{display:none;position:fixed;right:15px;bottom:15px;width:200px;max-height:270px;background:rgba(255,255,255,.85);border:1px solid #9aa99e}#info{font-size:14px}input[type=range]{width:150px}</style><header><b>两组图元动作试验</b><button onclick="act('action','idle')">基础姿势组</button><button onclick="act('action','move')">移动姿势组</button><button id="pause" onclick="act('pause',!data.paused?1:0)">播放</button><button onclick="act('step',1)">下一帧</button><label>帧 <input type="range" min="1" max="4" value="1" id="frame" oninput="act('frame',Number(this.value))"></label><button onclick="act('mirror',-data.mirror)">镜像</button><button onclick="act('position',0)">回到中央</button><label><input type="checkbox" id="reference" onchange="act('pause',1);document.querySelector('#ref').style.display=this.checked?'block':'none'">原图对照</label><a href="/animation.gia" download="草神_994图元_两组动作.gia">下载GIA</a><a href="/bundle.zip" download="草神_两组图元动作.zip">下载完整素材</a></header><p>每组4个源姿势，共用994个角色图片控件。A/D或左右键：移动并切至移动组；松开切回基础组。空格：播放/暂停。底色是透明网格，GIA中没有整屏背景图。</p><p id="info">加载中…</p><p>美术未验收：移动组屈腿和迈步仍明显偏离原图，固定站姿图元的匹配不足；本页用于检验操作与换帧。不是已完成的正式角色动画，真机未验证。</p><div id="stage"><img id="screen" alt="实际GIA回读后的透明模拟器画面"></div><img id="ref" alt="当前帧的去背景高清参考"><script>
let data={paused:true,mirror:1,position:0};let busy=false;
async function update(){const r=await fetch('/state');data=await r.json();document.querySelector('#pause').textContent=data.paused?'播放':'暂停';document.querySelector('#frame').value=data.frame;document.querySelector('#info').textContent=(data.action==='idle'?'基础姿势组':'移动姿势组')+' · '+data.frame+'/4 · 994图片池 · '+(data.paused?'暂停':'播放')+(data.errors.length?' · 运行错误':'');document.querySelector('#ref').src='/reference/'+data.action+'/'+(data.frame-1)+'.png';}
async function act(op,value){if(busy)return;busy=true;try{await fetch('/control',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({op,value})});await update();document.querySelector('#screen').src='/screen.png?t='+Date.now();}finally{busy=false;}}
const screen=document.querySelector('#screen');screen.onload=()=>setTimeout(()=>{screen.src='/screen.png?t='+Date.now()},160);screen.src='/screen.png';screen.onclick=e=>{const r=screen.getBoundingClientRect();const x=(e.clientX-r.left)/r.width*1600,y=(e.clientY-r.top)/r.height*900;if(y>778&&y<822){for(const [name,cx] of [['Basic',520],['Move',705],['Pause',895],['Step',1080]])if(Math.abs(x-cx)<83)act('button',name);}};update();setInterval(update,400);
window.addEventListener('keydown',e=>{if(['INPUT','BUTTON'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();act('pause',data.paused?0:1);}if(['KeyA','KeyD','ArrowLeft','ArrowRight'].includes(e.code)){e.preventDefault();const left=e.code==='KeyA'||e.code==='ArrowLeft';fetch('/control',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({op:'action',value:'move'})});fetch('/control',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({op:'pause',value:0})});act('position',Math.max(-400,Math.min(400,data.position+(left?-20:20))));}});
window.addEventListener('keyup',e=>{if(['KeyA','KeyD','ArrowLeft','ArrowRight'].includes(e.code))act('action','idle');});
</script></html>`;
createServer(async(req,res)=>{try{
 if(req.url==='/'){res.writeHead(200,{'content-type':'text/html;charset=utf-8'});res.end(html);return;}
 if(req.url==='/state'){res.writeHead(200,{'content-type':'application/json','cache-control':'no-store'});res.end(JSON.stringify(state()));return;}
 if(req.url.startsWith('/screen.png')){const s=studio.playGet({view:true,paint:true});res.writeHead(200,{'content-type':'image/png','cache-control':'no-store'});res.end(renderPaintPng(s.paint,s.canvasWidth,s.canvasHeight).data);return;}
 if(req.url==='/control'&&req.method==='POST'){let body='';for await(const c of req){body+=c;if(body.length>1000)throw Error('Body too large');}const v=JSON.parse(body);if(v.op==='button'&&['Basic','Move','Pause','Step'].includes(v.value)){studio.playClick(v.value,{observe:false});studio.playStep(1/60,{observe:false});paused=state().status.includes('paused');}else{if(!['action','pause','step','frame','mirror','position'].includes(v.op))throw Error('Unknown control');command(v.op,v.value);}res.writeHead(200,{'content-type':'application/json'});res.end(JSON.stringify(state()));return;}
 const reference=/^\/reference\/(idle|move)\/([0-3])\.png$/.exec(req.url);
 if(reference){res.writeHead(200,{'content-type':'image/png'});fs.createReadStream(OUT+'/'+reference[1]+'/'+reference[2]+'/reference.png').pipe(res);return;}
 const files={'/animation.gia':['草神_994图元_两组动作.gia','application/octet-stream'],'/bundle.zip':['草神_两组图元动作.zip','application/zip']};
 if(files[req.url]){res.writeHead(200,{'content-type':files[req.url][1]});fs.createReadStream(OUT+'/'+files[req.url][0]).pipe(res);return;}
 res.writeHead(404);res.end();
}catch(e){res.writeHead(500,{'content-type':'application/json'});res.end(JSON.stringify({error:String(e.message)}));}}).listen(8827,'127.0.0.1',()=>console.log('http://127.0.0.1:8827/'));
